require __DIR__.'/auth.php';require __DIR__.'/config.php';header('Content-Type: application/json; charset=utf-8');$u=require_login();if(empty($STRIPE_SECRET_KEY)){http_response_code(500);echo json_encode(['error'=>'Stripe key not configured']);exit;}$scans=max(1,min(100,(int)($_POST['scans']??1)));$amount=(int)round($scans*$PRICE_PER_SCAN*100);$invoice='BIRD-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$s=$pdo->prepare("INSERT INTO payments(user_id,invoice_id,amount,scans,status,provider) VALUES(?,?,?,?, 'pending','stripe')");$s->execute([$u['id'],$invoice,$amount/100,$scans]);$p=['mode'=>'payment','success_url'=>$APP_URL.'/?stripe=success','cancel_url'=>$APP_URL.'/?stripe=cancelled','client_reference_id'=>$invoice,'line_items[0][price_data][currency]'=>strtolower($CURRENCY),'line_items[0][price_data][product_data][name]'=>'Bird ID Scan Credit','line_items[0][price_data][unit_amount]'=>$amount,'line_items[0][quantity]'=>1,'metadata[invoice_id]'=>$invoice,'metadata[user_id]'=>$u['id'],'metadata[scans]'=>$scans];$ch=curl_init('https://api.stripe.com/v1/checkout/sessions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_USERPWD=>$STRIPE_SECRET_KEY.':',CURLOPT_POSTFIELDS=>http_build_query($p),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30]);$res=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$o=json_decode($res,true);if($http>=400){http_response_code(502);echo json_encode(['error'=>$o['error']['message']??'Stripe error']);exit;}$s=$pdo->prepare('UPDATE payments SET trx_id=? WHERE invoice_id=?');$s->execute([$o['id'],$invoice]);echo json_encode(['ok'=>true,'checkout_url'=>$o['url'],'invoice_id'=>$invoice]);
